import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import { GrammarCard } from "@/components/review/grammar-card";

describe("GrammarCard", () => {
  it("shows the example and the corrected form", () => {
    render(<GrammarCard example="Heute ich gehe" corrected="Heute gehe ich" />);

    expect(screen.getByText("Heute ich gehe")).toBeVisible();
    expect(screen.getByText("Heute gehe ich")).toBeVisible();
  });
});
